const inp = $('Receive request').first().json;
const meta = $('Get repo').first().json;
const res = $input.first().json;
const EXT = /\.(js|jsx|ts|tsx|vue|svelte|html|hbs|mjml|njk|ejs|json|svg|py|ya?ml|php|twig|liquid)$/i;
const SKIP = /(^|\/)(node_modules|dist|build|\.next|coverage|__tests__|__mocks__|mocks?|fixtures|storybook|\.storybook|e2e|cypress|playwright|tests?|migrations|\.github)(\/|$)|\.(test|spec|stories)\.[jt]sx?$|\.d\.ts$|(package-lock|yarn\.lock|pnpm-lock)|(^|\/)tsconfig[^/]*$/i;
const isLoc = p => /(^|\/)(locales?|i18n|messages|translations?|lang)\//i.test(p) || /(^|\/)(en|en-US|en_US)\.json$/.test(p);
let files = (res.tree || []).filter(t => t.type === 'blob' && EXT.test(t.path) && !SKIP.test(t.path) && (t.size || 0) < 600000);
files = files.filter(t => !/\.json$/i.test(t.path) || isLoc(t.path) || /(^|\/)package\.json$/.test(t.path));
return [{ json: { owner: inp.owner || 'QR-CODE-App', repo: inp.repo, ref: inp.ref || meta.default_branch, default_branch: meta.default_branch, tree_truncated: !!res.truncated, count: files.length, files: files.map(f => ({ path: f.path, size: f.size })) } }];

const inp = $('Receive request').first().json;
let paths = [];
try { paths = JSON.parse(inp.paths || '[]'); } catch (e) { paths = String(inp.paths || '').split(',').map(s => s.trim()).filter(Boolean); }
if (!inp.repo || !inp.ref) throw new Error('repo and ref are required (take ref from repo_tree)');
return paths.slice(0, 150).map(p => ({ json: { owner: inp.owner || 'QR-CODE-App', repo: inp.repo, ref: inp.ref, path: p } }));

const src = $('Split paths').all();
const files = $input.all().map((it, i) => ({ path: src[i] ? src[i].json.path : null, content: typeof it.json.data === 'string' ? it.json.data : null, error: it.json.error ? String(it.json.error.message || it.json.error) : undefined }));
return [{ json: { count: files.length, missing: files.filter(f => f.content === null).map(f => f.path), chars: files.reduce((s, f) => s + (f.content ? f.content.length : 0), 0), files, note: 'Max 150 paths per call; call again for the next batch.' } }];

const inp = $('Receive request').first().json;
const want = String(inp.locales || '').split(',').map(s => s.trim()).filter(Boolean);
const all = $input.first().json.languages || [];
const m = (l, w) => l.lang_iso === w || l.lang_iso.startsWith(w + '_') || l.lang_iso.startsWith(w + '-');
const pick = all.filter(l => l.lang_iso === 'en' || want.some(w => m(l, w)));
return [{ json: { ids: pick.map(l => l.lang_id).join(','), codes: pick.map(l => l.lang_iso), not_in_project: want.filter(w => !all.some(l => m(l, w))) } }];

const inp = $('Receive request').first().json;
const lang = $('Pick languages').first().json;
let strings = []; try { strings = JSON.parse(inp.strings || '[]'); } catch (e) { strings = []; }
const norm = s => String(s).replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
const want = new Set(strings.map(norm));
const keys = $input.all().flatMap(i => Array.isArray(i.json.keys) ? i.json.keys : []);
const matches = {}; const en_values = []; let archived = 0;
for (const k of keys) {
  if (k.is_archived) { archived++; continue; }
  const t = {}; let en = null;
  for (const tr of (k.translations || [])) {
    let v = tr.translation;
    if (k.is_plural) { try { const o = JSON.parse(v); v = o.other != null ? o.other : Object.values(o)[0]; } catch (e) {} }
    if (tr.language_iso === 'en') en = v; else if (v) t[tr.language_iso] = v;
  }
  if (en == null || en === '') continue;
  const n = norm(en);
  if (en_values.length < 10000) en_values.push(n);
  if (want.has(n) && !matches[n]) { const kn = k.key_name || {}; matches[n] = { key: kn.web || kn.other || Object.values(kn)[0], plural: !!k.is_plural, t }; }
}
return [{ json: { project_id: inp.project_id, languages: lang.codes, not_in_project: lang.not_in_project, keys_seen: keys.length, archived_skipped: archived, matched: Object.keys(matches).length, matches, en_values } }];

const q = String($('Receive request').first().json.product || '');
const res = $input.first().json.results || [];
const n = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
const hit = res.find(p => n(p.title) === n(q)) || res.find(p => n(q) && n(p.title).includes(n(q))) || res.find(p => n(p.title) && n(q).includes(n(p.title)));
return [{ json: { page_id: hit ? hit.id : '', title: hit ? hit.title : '', candidates: res.map(p => p.title) } }];

const pick = $('Pick product page').first().json;
const p = $input.first().json;
let h = (p.body && p.body.storage && p.body.storage.value) || '';
h = h.replace(/<\/(tr|p|h\d|li)>/gi, '\n').replace(/<\/(td|th)>/gi, ' | ').replace(/<a [^>]*href="([^"]+)"[^>]*>/gi, ' $1 ').replace(/<ri:url ri:value="([^"]+)"[^>]*>/gi, ' $1 ').replace(/<[^>]+>/g, '');
h = h.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
if (!pick.page_id) return [{ json: { found: false, note: 'No Language support page matched this product. Ask which candidate is meant.', candidates: pick.candidates } }];
return [{ json: { found: true, title: pick.title, page_url: 'https://futuremedia.atlassian.net/wiki/pages/viewpage.action?pageId=' + pick.page_id, text: h.slice(0, 20000), candidates: pick.candidates } }];

