const r = $input.first().json;
const text = d => { if (!d) return ''; if (typeof d === 'string') return d; const out = []; const walk = n => { if (!n) return; if (n.text) out.push(n.text); (n.content || []).forEach(walk); }; walk(d); return out.join(' '); };
const issues = (r.issues || []).map(i => ({ key: i.key, url: 'https://futuremedia.atlassian.net/browse/' + i.key, summary: i.fields.summary, status: i.fields.status && i.fields.status.name, status_category: i.fields.status && i.fields.status.statusCategory && i.fields.status.statusCategory.key, created: i.fields.created, labels: i.fields.labels, description: text(i.fields.description).slice(0, 2000) }));
return [{ json: { jira_project: $('Receive request').first().json.jira_project, count: issues.length, is_last: r.isLast !== false, issues } }];

const q = String($('Receive request').first().json.product || '').toLowerCase().trim();
const all = $input.first().json.value || [];
const hits = all.filter(f => /\.xlsx$/i.test(f.name) && /i18n pre-check/i.test(f.name) && q && f.name.toLowerCase().includes(q))
  .sort((a, b) => String(b.lastModifiedDateTime).localeCompare(String(a.lastModifiedDateTime)))
  .slice(0, 3);
if (!hits.length) return [{ json: { none: true, product: q } }];
return hits.map(f => ({ json: { id: f.id, name: f.name, webUrl: f.webUrl, modified: f.lastModifiedDateTime } }));

const src = $('Pick product workbooks').all();
if (src.length === 1 && src[0].json.none) return [{ json: { count: 0, files: [], note: 'No earlier i18n pre-check workbook for this product in AI AUDITS.' } }];
const files = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const meta = src[i] ? src[i].json : {};
  let b64 = null;
  try { const buf = await this.helpers.getBinaryDataBuffer(i, 'data'); b64 = buf.toString('base64'); } catch (e) { b64 = null; }
  files.push({ name: meta.name, webUrl: meta.webUrl, modified: meta.modified, base64: b64 });
}
return [{ json: { count: files.length, files, note: 'Newest first. Decode base64 to .xlsx and read Decision / Rejection reason / Fingerprint.' } }];
